starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "zone_id" {
  description = "Input variable zone_id."
  type        = string
}

variable "record_name" {
  description = "Input variable record_name."
  type        = string
  default     = "app"
}

variable "record_value" {
  description = "Input variable record_value."
  type        = string
  default     = "203.0.113.10"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_route53_record" "this" {
  # TODO - Complete the aws_route53_record resource.
  # Add the arguments and nested blocks required for aws_route53_record.
}
